import{_ as t,o,c as a,a0 as d}from"./chunks/framework.Chtk_IOO.js";const m=JSON.parse('{"title":"Port is the transport — integration plan","description":"","frontmatter":{},"headers":[],"relativePath":"Port-Namespace-Integration-Plan.md","filePath":"Port-Namespace-Integration-Plan.md"}'),n={name:"Port-Namespace-Integration-Plan.md"};function r(s,e,c,i,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="port-is-the-transport-—-integration-plan" tabindex="-1">Port is the transport — integration plan <a class="header-anchor" href="#port-is-the-transport-—-integration-plan" aria-label="Permalink to &quot;Port is the transport — integration plan&quot;">​</a></h1><p>Status 2026-10-15. Nothing here is integrated, published or deployed. Everything below was measured in isolated worktrees and disposable processes.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A port belongs to the transport, never to the namespace. <code>name.space</code> and <code>name.space:8080</code> name the same namespace and are two transports; nothing (verification, session, credentials) passes between them; an explicit door is the only door; the same person coming back in is the same identity, and the identity a sign-in attempts is said before anything is signed.</p><h2 id="names-addresses-and-identity-are-three-different-things" tabindex="-1">Names, addresses and identity are three different things <a class="header-anchor" href="#names-addresses-and-identity-are-three-different-things" aria-label="Permalink to &quot;Names, addresses and identity are three different things&quot;">​</a></h2><ul><li>A <strong>canonical name</strong> (<code>name.space</code>, what the monad canonicalizes a loopback to) is a spelling the system agrees on.</li><li>A <strong>network address</strong> (a host, a port, an origin) is where a request goes.</li><li>A <strong>verifiable identity</strong> is evidence that the actor behind a name is the same one as before (a signature, a claim, an authority record).</li></ul><p>Canonicalizing a name proves none of the other two. <code>suis-macbook-air.local</code> is not globally unique (another network can have the same <code>.local</code> name); <code>localhost</code> and <code>127.0.0.1</code> mean &quot;this machine&quot; wherever they are read; <code>cleaker.me</code> is a DNS name whose control can change. &quot;The same namespace&quot; in this plan means &quot;the same name&quot;, not &quot;the same actor or tree&quot;: that continuity needs the evidence the claim flow already asks for (signed proofs against a claim), and nothing in this change weakens or replaces it.</p><h2 id="a-signed-proof-goes-only-to-a-destination-that-was-selected" tabindex="-1">A signed proof goes only to a destination that was selected <a class="header-anchor" href="#a-signed-proof-goes-only-to-a-destination-that-was-selected" aria-label="Permalink to &quot;A signed proof goes only to a destination that was selected&quot;">​</a></h2><p><code>signIn</code>/<code>claim</code> present a signature. Discovery may list candidates; a signature is presented only to: the origins the node was built for (preferred/space/bootstrap), the explicit <code>fallbackOrigins</code> (empty by default), what the page location or the operator&#39;s environment names, and the origin the signed namespace itself names. The machine hostname and the built-in defaults (public <code>cleaker.me</code>, <code>localhost</code>) are guesses: they no longer receive a proof when the primary fails (cleaker K13–K16). An explicit door (<code>name.space:9901</code>) is the ONLY door.</p><h2 id="exact-inputs" tabindex="-1">Exact inputs <a class="header-anchor" href="#exact-inputs" aria-label="Permalink to &quot;Exact inputs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Where</th><th>Version</th><th>Commit</th></tr></thead><tbody><tr><td>cleaker</td><td><code>all.this/cleaker-port-namespace</code> (<code>fix/port-not-in-namespace</code>, cut from <code>fix/normalize-surface-origin-port</code> @ <code>ee519ef</code>)</td><td><code>cleaker@4.0.0</code> (field unchanged; bump on integration)</td><td><code>4f66f4b</code></td></tr><tr><td>GUI</td><td><code>all.this/gui-port-namespace</code> (<code>fix/port-not-in-namespace</code>, cut from <code>feat/rail-beetle-icon</code> @ <code>4765d81b</code>)</td><td><code>this.gui@4.1.0</code></td><td><code>d8519bf0</code></td></tr><tr><td>monad</td><td><code>all.this/monad-candidate</code> (<code>candidate/r20261014-1</code>) — <strong>no source change</strong></td><td><code>monad.ai@3.0.0</code></td><td><code>ef4320e7</code></td></tr><tr><td>this.me used to run monad&#39;s tests</td><td>release <code>r20261014-1</code></td><td><code>this.me@4.2.0</code></td><td>(release tree)</td></tr><tr><td>netget</td><td><code>all.this/netget-main-entry</code> (<code>feat/door-connections</code>) — <strong>no source change</strong></td><td><code>netget@2.7.7</code> (depends on published <code>cleaker ^3.2.1</code>)</td><td><code>f0d4b8b</code></td></tr></tbody></table><p>GUI and monad depend on cleaker as <code>workspace:*</code> (no version pin). <strong>netget depends on the published <code>cleaker ^3.2.1</code>, so it does not see this change until a cleaker release exists.</strong></p><h2 id="what-each-repo-changes" tabindex="-1">What each repo changes <a class="header-anchor" href="#what-each-repo-changes" aria-label="Permalink to &quot;What each repo changes&quot;">​</a></h2><ul><li><strong>cleaker</strong> (4 commits): parser (<code>fqdn</code>/<code>constant</code> bare, port in <code>transport</code>, <code>expression</code> round-trips); binder (written port applied to the transport it names, scheme kept; <code>TRANSPORT_PORT_CONFLICT</code>; an explicit door is the ONLY door — no fallback receives a signed proof; namespaces signed/sent/compared bare). Tests NS1 and NRP4 changed on purpose.</li><li><strong>GUI</strong>: parser mirror; <code>splitTypedNamespace</code> ignores a root&#39;s port; identity vault found by namespace (any spelling), conflicts asked (<code>VAULT_CONFLICT</code>), originals kept; <code>chooseIdentityMechanism</code>; <code>TRANSPORT_PORT_CONFLICT</code> on the card; the mechanism is said before signing; <code>checkWrittenDoor</code> in <code>link.ts</code>.</li><li><strong>monad</strong>: none. Its parser consumers read <code>constant</code>/<code>prefix</code>/<code>fqdn</code> and already strip ports (<code>stripPort</code>, <code>canonicalizeNamespaceConstant</code>); measured below.</li></ul><h2 id="monad-routes-that-consume-the-parser-measured-not-assumed" tabindex="-1">Monad routes that consume the parser (measured, not assumed) <a class="header-anchor" href="#monad-routes-that-consume-the-parser-measured-not-assumed" aria-label="Permalink to &quot;Monad routes that consume the parser (measured, not assumed)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Reads</th><th>Suite (new cleaker)</th></tr></thead><tbody><tr><td><code>namespace/identity.ts</code></td><td><code>constant</code>, <code>prefix</code> (+ <code>stripPort</code>)</td><td>via the suites below</td></tr><tr><td><code>kernel/manager.ts</code></td><td><code>constant</code>, <code>prefix</code> → kernel prefix / root test</td><td><code>kernelManagerNamespace</code> 3/3, <code>namespaceRootIsolation</code> 9/9</td></tr><tr><td><code>claim/gatewayAuthority.ts</code></td><td><code>constant</code></td><td><code>gatewayAuthority</code> 10/10</td></tr><tr><td><code>claim/appAuthorization.ts</code>, <code>groupAuthorization.ts</code></td><td>namespace identity</td><td><code>appAuthorization</code> 3/3, <code>namespaceCollisionAuthorization</code> 3/3</td></tr><tr><td><code>runtime/bridge.ts</code></td><td><code>parseNrpTarget(...).fqdn</code> → <code>normalizeNamespaceIdentity</code></td><td><code>NRP/bridge.parse</code> 16/16</td></tr><tr><td><code>http/nrpHandler.ts</code></td><td>wire AST <code>parsed.fqdn</code></td><td><code>NRP/nrpHandler</code> 5/5, <code>NRP/nrpDeclaredRoot</code> 7/7</td></tr></tbody></table><p>Whole monad-candidate suite, same <code>this.me@4.2.0</code>: <strong>cleaker <code>ee519ef</code> 669 pass / 5 fail; cleaker <code>9587508</code> 669 pass / 5 fail; 0 tests change status.</strong> The 5 failures exist before this change and are not parser-related (a polls id, a deep-equal, a fingerprint, an array match). Caveat: with the repo-linked <code>this.me</code> (stale <code>dist</code>) 126 tests cannot run at all (<code>IncompatibleMeError</code>); the numbers above are from the release&#39;s <code>this.me</code>.</p><h2 id="behaviors-worth-a-decision-before-integrating" tabindex="-1">Behaviors worth a decision before integrating <a class="header-anchor" href="#behaviors-worth-a-decision-before-integrating" aria-label="Permalink to &quot;Behaviors worth a decision before integrating&quot;">​</a></h2><ol><li><strong>Fallback policy for addresses that named NO door.</strong> Measured (K14): with <code>name.space</code> unreachable, signed open proofs are sent to <code>https://cleaker.me/claims/signIn</code> and <code>http://localhost/claims/signIn</code>. This predates the change. An explicit door no longer does this; a bare address still does. Proposal: an explicit <code>fallbackOrigins</code> option, default empty for non-public roots.</li><li><strong><code>localhost</code> is one namespace across ports</strong> (NS1 compat change). Several local monads that were distinguished only by port now need distinct names.</li><li><strong>Legacy <code>monad</code> session backend</strong> (<code>createSeedSession.buildProof</code>): not characterized, not claimed compatible.</li></ol><h2 id="the-gui-topic-branch-separated-from-the-large-branch" tabindex="-1">The GUI topic branch (separated from the large branch) <a class="header-anchor" href="#the-gui-topic-branch-separated-from-the-large-branch" aria-label="Permalink to &quot;The GUI topic branch (separated from the large branch)&quot;">​</a></h2><p><code>feat/rail-beetle-icon</code> is 127 commits over <code>7213a2c1</code> and mixes themes. The port work needs the <strong>shell restructure</strong> (<code>&lt;Me&gt;</code>/<code>&lt;Cleaker&gt;</code>/<code>QRConnect</code>/per-link sessions, commits 6–82 and the <code>origin/main</code> merge <code>cb79c8e0</code>) and not the rail, orb or corner work. Built by cherry-pick, <code>topic/port-namespace</code> (worktree <code>all.this/gui-port-isolated</code>):</p><pre><code>cb79c8e0  (shell restructure + origin/main merge)\n  + identity card / position label chain (84–98, `fad683fd` … `c89f29c4`)\n  + top bar address, /.me page, welcome (110–113), `f85468a0` card namespace\n  + link model (`d7804e94`), integration harness (`862e90d8`), per-link sessions (`c1a158c8`), workspace (`4765d81b`)\n  + port: tests, vault, parser/door conflict, mechanism note, this plan\n</code></pre><p>Left out on purpose: orb icon work (99–109), left-bar corner/QR control (118–121), <code>13152626</code> (QR carries the namespace + spacing; the IPv4 parser fix inside it was folded into the parser commit). Conflicts resolved by hand: <code>package.json</code> (kept as it was; test entries re-added), <code>namespaceExpression.ts</code> (the IPv4 branch), <code>QRConnect.tsx</code> (one import), <code>links.browser.test.mjs</code> (sections 6–7 belong to the skipped commits).</p><p>Verified on the topic: link 3 groups, port-namespace vault 11 / parser 7 / mechanism 4 / contract 4, browser integration 32/32 (sections 1–5, 8–10). NOT verified: that this topic also builds against today&#39;s <code>main</code> (4.2.0, deps from npm, no <code>QRConnect</code>): <code>main</code> does not contain the shell restructure either, so the topic is based on the restructure&#39;s own merge point; landing on <code>main</code> needs the restructure to land first.</p><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h2><ol><li>GUI: land the link model first (<code>link.ts</code>, per-link sessions in <code>SeedSessionProvider</code>) — the port commits build on it (<code>checkWrittenDoor</code>, <code>explicit</code>/<code>openLinks</code>). <code>feat/rail-beetle-icon</code> is still 126 commits and mixed (WP0); split before merging, then cherry-pick the 5 port commits (<code>63fdef82</code>, <code>c87e7c63</code>, <code>b26cec18</code>, <code>d8519bf0</code>, + docs).</li><li>cleaker: merge <code>fix/port-not-in-namespace</code> after <code>fix/normalize-surface-origin-port</code>; bump a minor (behavioral change in <code>fqdn</code>/<code>constant</code>) and publish; then netget&#39;s <code>^3.2.1</code> range needs an explicit decision (it is a different major line).</li><li>monad: no source change; rebuild its release against the new cleaker and run the suite above plus the live path.</li><li>Release candidate assembled from exact SHAs (no floating <code>workspace:*</code> between rehearsal and activation).</li></ol><h2 id="final-check-disposable-nothing-in-production" tabindex="-1">Final check (disposable, nothing in production) <a class="header-anchor" href="#final-check-disposable-nothing-in-production" aria-label="Permalink to &quot;Final check (disposable, nothing in production)&quot;">​</a></h2><p>The development path, on a disposable OpenResty/netget and disposable monads, throwaway identities, killed by PID:</p><ol><li>Interface served by netget at the dev door (<code>fulltrailer.&lt;host&gt;:80</code>), API on <code>:9901</code> as a separate monad/server.</li><li>Namespace of the interface is the same whether it is reached on <code>:80</code> or <code>:9901</code>; verification and session do NOT cross.</li><li><code>name.space:9901</code> unreachable → fails there; the destinations contacted are recorded; no signed proof elsewhere.</li><li>Phrase identity and password identity both re-enter through either spelling; two old vaults → conflict asked.</li><li>Rollback = the previous release; cleaker/GUI changes are additive to stored data (vault originals kept).</li></ol>',29)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
